/**
 * @claude-flow/codex - Generators
 *
 * Template generation functions for AGENTS.md, SKILL.md, and config.toml
 */

export { generateAgentsMd } from './agents-md.js';
export { generateSkillMd } from './skill-md.js';
export { generateConfigToml } from './config-toml.js';

/**
 * @claude-flow/codex - SKILL.md Generator
 *
 * Custom skills are rendered from typed options. Built-in skills use the
 * packaged `.agents/skills` trees as their canonical definitions so direct
 * generation, project initialization, and npm artifacts cannot drift.
 */

import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { BuiltInSkill, SkillMdOptions, SkillCommand } from '../types.js';

export const BUILT_IN_SKILL_NAMES: readonly BuiltInSkill[] = [
  'swarm-orchestration',
  'memory-management',
  'sparc-methodology',
  'security-audit',
  'performance-analysis',
  'github-automation',
];

const BUILT_IN_SKILLS_ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../.agents/skills',
);

/**
 * Generate a SKILL.md file based on the provided options.
 */
export async function generateSkillMd(options: SkillMdOptions): Promise<string> {
  const {
    name,
    description,
    version = '1.0.0',
    author = 'rUv',
    tags,
    triggers = [],
    skipWhen = [],
    scripts = [],
    references = [],
    commands = [],
  } = options;

  const tagList = tags && tags.length > 0 ? tags : name.split('-').filter(Boolean);
  const triggerText = triggers.length > 0
    ? `Use when: ${triggers.join(', ')}.`
    : '';
  const skipText = skipWhen.length > 0
    ? `Skip when: ${skipWhen.join(', ')}.`
    : '';

  const frontmatter = `---
name: ${name}
version: "${version}"
author: ${author}
tags: [${tagList.join(', ')}]
description: >
  ${description}
  ${triggerText}
  ${skipText}
---`;

  const commandsSection = commands.length > 0 ? buildCommandsSection(commands) : '';
  const scriptsSection = scripts.length > 0 ? buildScriptsSection(scripts) : '';
  const referencesSection = references.length > 0 ? buildReferencesSection(references) : '';

  return `${frontmatter}

# ${formatSkillName(name)} Skill

## Purpose
${description}

## When to Trigger
${triggers.length > 0 ? triggers.map(t => `- ${t}`).join('\n') : '- Define triggers for this skill'}

## When to Skip
${skipWhen.length > 0 ? skipWhen.map(s => `- ${s}`).join('\n') : '- Define skip conditions for this skill'}
${commandsSection}
${scriptsSection}
${referencesSection}
## Best Practices
1. Check memory for existing patterns before starting
2. Use hierarchical topology for coordination
3. Store successful patterns after completion
4. Document any new learnings
`;
}

function buildCommandsSection(commands: SkillCommand[]): string {
  const lines = commands.map(cmd => {
    let block = `### ${cmd.name}\n${cmd.description}\n\n\`\`\`bash\n${cmd.command}\n\`\`\``;
    if (cmd.example) {
      block += `\n\n**Example:**\n\`\`\`bash\n${cmd.example}\n\`\`\``;
    }
    return block;
  });

  return `
## Commands

${lines.join('\n\n')}
`;
}

function buildScriptsSection(scripts: { name: string; path: string; description: string }[]): string {
  const lines = scripts.map(s => `| \`${s.name}\` | \`${s.path}\` | ${s.description} |`);

  return `
## Scripts

| Script | Path | Description |
|--------|------|-------------|
${lines.join('\n')}
`;
}

function buildReferencesSection(references: { name: string; path: string; description?: string }[]): string {
  const lines = references.map(r =>
    `| \`${r.name}\` | \`${r.path}\` | ${r.description ?? ''} |`
  );

  return `
## References

| Document | Path | Description |
|----------|------|-------------|
${lines.join('\n')}
`;
}

function formatSkillName(name: string): string {
  return name
    .split('-')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

async function readPayloadTree(root: string): Promise<Record<string, string>> {
  const payload: Record<string, string> = {};

  async function visit(directory: string): Promise<void> {
    let entries;
    try {
      entries = await readdir(directory, { withFileTypes: true });
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === 'ENOENT') return;
      throw error;
    }

    for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
      const absolute = path.join(directory, entry.name);
      if (entry.isSymbolicLink()) {
        throw new Error(`Built-in skill payload cannot contain symlinks: ${absolute}`);
      }
      if (entry.isDirectory()) {
        await visit(absolute);
      } else if (entry.isFile()) {
        const relative = path.relative(root, absolute);
        if (relative.startsWith('..') || path.isAbsolute(relative)) {
          throw new Error(`Built-in skill payload escapes its root: ${absolute}`);
        }
        const payloadPath = relative.split(path.sep).join('/');
        payload[payloadPath] = await readFile(absolute, 'utf8');
      }
    }
  }

  await visit(root);
  return payload;
}

/**
 * Read one canonical built-in tree from the package payload.
 */
export async function generateBuiltInSkill(
  skillName: string,
): Promise<{ skillMd: string; scripts: Record<string, string>; references: Record<string, string> }> {
  if (!BUILT_IN_SKILL_NAMES.includes(skillName as BuiltInSkill)) {
    throw new Error(`Unknown built-in skill: ${skillName}`);
  }

  const skillRoot = path.join(BUILT_IN_SKILLS_ROOT, skillName);
  let skillMd: string;
  try {
    skillMd = await readFile(path.join(skillRoot, 'SKILL.md'), 'utf8');
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      throw new Error(`Built-in skill payload missing: ${skillName}/SKILL.md`);
    }
    throw error;
  }

  const result = {
    skillMd,
    scripts: await readPayloadTree(path.join(skillRoot, 'scripts')),
    references: await readPayloadTree(path.join(skillRoot, 'references')),
  };
  validateBuiltInSkillPayload(skillName, result.skillMd, result.scripts, result.references);
  return result;
}

/**
 * Ensure every skill-local path is contained in and shipped with its tree.
 */
export function validateBuiltInSkillPayload(
  skillName: string,
  skillMd: string,
  scripts: Record<string, string>,
  references: Record<string, string>,
): void {
  const localPaths = Array.from(
    skillMd.matchAll(/`((?:scripts|references)\/[^`\s]+)`/g),
    (match) => match[1]!,
  );

  for (const localPath of localPaths) {
    const normalized = path.posix.normalize(localPath.replaceAll('\\', '/'));
    if (normalized.startsWith('../') || path.posix.isAbsolute(normalized)) {
      throw new Error(`Built-in skill path escapes ${skillName}: ${localPath}`);
    }
    const slash = normalized.indexOf('/');
    const directory = normalized.slice(0, slash);
    const payloadPath = normalized.slice(slash + 1);
    const payload = directory === 'scripts' ? scripts : references;
    if (!Object.hasOwn(payload, payloadPath)) {
      throw new Error(`Built-in skill payload missing: ${skillName}/${normalized}`);
    }
  }
}

import { createHash } from 'node:crypto';
import { lstatSync, readFileSync, readlinkSync, realpathSync } from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';
import {
  canonicalJson,
  captureRepositorySourceState,
  type ExactSourceState,
} from './repository-state.js';
import { portableCaseFold } from './portable-case-fold.js';

const DIGEST = /^sha256:[0-9a-f]{64}$/;

export interface DeclaredBuildInput {
  name: string;
  /** Repository-relative declaration; it may name an ignored generated input. */
  path: string;
  digest: string;
  bytes: number;
}

export interface DeclaredToolchain {
  name: string;
  version: string;
  /** Digest of the executable, image, lock, or immutable toolchain manifest. */
  digest: string;
}

export interface BuildInputDeclaration {
  name: string;
  path: string;
}

export interface ToolchainDeclaration {
  name: string;
  version: string;
  /** Local executable or immutable manifest to hash; not embedded in evidence. */
  path: string;
}

export interface BuildEvidence {
  contractVersion: 1;
  assurance: 'declared-unsigned';
  sourceStateId: string;
  buildInputs: readonly DeclaredBuildInput[];
  toolchains: readonly DeclaredToolchain[];
  evidenceDigest: string;
}

function compare(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function requireText(value: string, label: string): string {
  const result = value.trim();
  if (!result) throw new Error(`${label} must be non-empty`);
  return result;
}

function requireDigest(value: string, label: string): string {
  if (!DIGEST.test(value)) throw new Error(`${label} must be a canonical sha256 digest`);
  return value;
}

function normalizePath(value: string): string {
  const path = requireText(value, 'build input path');
  if (
    path.includes('\\')
    || path.startsWith('/')
    || path.startsWith('-')
    || path !== path.normalize('NFC')
    || path.split('/').some((part) => !part || part === '.' || part === '..')
  ) {
    throw new Error(`unsafe build input path: ${value}`);
  }
  return path;
}

function sha256(value: string): string {
  return `sha256:${createHash('sha256').update(value).digest('hex')}`;
}

function digestPath(path: string, followSymlink: boolean): { digest: string; bytes: number } {
  const resolved = followSymlink ? realpathSync(path) : path;
  const stat = lstatSync(resolved);
  const content = stat.isSymbolicLink()
    ? Buffer.from(readlinkSync(resolved), 'utf8')
    : stat.isFile()
      ? readFileSync(resolved)
      : undefined;
  if (!content) throw new Error(`build evidence path is not a file or symlink: ${path}`);
  return {
    digest: `sha256:${createHash('sha256').update(content).digest('hex')}`,
    bytes: content.byteLength,
  };
}

/**
 * Bind explicitly declared non-Git inputs and toolchains to one Git-visible
 * source state. This does not claim completeness; policy decides which
 * declarations are required for a release profile.
 */
export function createBuildEvidence(
  sourceState: ExactSourceState,
  buildInputs: readonly DeclaredBuildInput[],
  toolchains: readonly DeclaredToolchain[],
): BuildEvidence {
  const inputs = buildInputs.map((input) => ({
    name: requireText(input.name, 'build input name'),
    path: normalizePath(input.path),
    digest: requireDigest(input.digest, 'build input digest'),
    bytes: input.bytes,
  })).sort((left, right) => compare(left.path, right.path) || compare(left.name, right.name));
  const tools = toolchains.map((toolchain) => ({
    name: requireText(toolchain.name, 'toolchain name'),
    version: requireText(toolchain.version, 'toolchain version'),
    digest: requireDigest(toolchain.digest, 'toolchain digest'),
  })).sort((left, right) => compare(left.name, right.name) || compare(left.version, right.version));

  if (inputs.some(({ bytes }) => !Number.isSafeInteger(bytes) || bytes < 0)) {
    throw new Error('build input bytes must be a non-negative safe integer');
  }
  const inputKeys = inputs.map(({ name, path }) => `${name}\0${path}`);
  if (new Set(inputKeys).size !== inputKeys.length) throw new Error('duplicate declared build input');
  const foldedPaths = inputs.map(({ path }) => portableCaseFold(path));
  if (new Set(foldedPaths).size !== foldedPaths.length) {
    throw new Error('case-fold collision in declared build inputs');
  }
  const toolKeys = tools.map(({ name, version }) => `${name}\0${version}`);
  if (new Set(toolKeys).size !== toolKeys.length) throw new Error('duplicate declared toolchain');

  const body = {
    contractVersion: 1 as const,
    assurance: 'declared-unsigned' as const,
    sourceStateId: requireDigest(sourceState.sourceStateId, 'source state id'),
    buildInputs: inputs,
    toolchains: tools,
  };
  return { ...body, evidenceDigest: sha256(canonicalJson(body)) };
}

/**
 * Recompute declared evidence from local bytes. It does not prove the
 * declaration set is complete and does not sign or authorize a release.
 */
export function captureBuildEvidence(
  repoPath: string,
  sourceState: ExactSourceState,
  buildInputs: readonly BuildInputDeclaration[],
  toolchains: readonly ToolchainDeclaration[],
): BuildEvidence {
  const repoRoot = realpathSync(resolve(repoPath));
  if (captureRepositorySourceState(repoRoot).sourceStateId !== sourceState.sourceStateId) {
    throw new Error('Git-visible source state does not match the build evidence request');
  }
  const inputs = buildInputs.map((declaration): DeclaredBuildInput => {
    const path = normalizePath(declaration.path);
    const absolute = resolve(repoRoot, path);
    const real = realpathSync(absolute);
    const rel = relative(repoRoot, real);
    if (rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)) {
      throw new Error(`build input escapes repository: ${path}`);
    }
    return { name: declaration.name, path, ...digestPath(real, true) };
  });
  const tools = toolchains.map((declaration): DeclaredToolchain => ({
    name: declaration.name,
    version: declaration.version,
    digest: digestPath(
      isAbsolute(declaration.path) ? declaration.path : resolve(repoRoot, declaration.path),
      true,
    ).digest,
  }));
  return createBuildEvidence(sourceState, inputs, tools);
}

export function recomputeBuildEvidence(
  repoPath: string,
  expected: BuildEvidence,
  toolchains: readonly ToolchainDeclaration[],
): BuildEvidence {
  const sourceState = captureRepositorySourceState(repoPath);
  if (sourceState.sourceStateId !== expected.sourceStateId) {
    throw new Error('Git-visible source state changed before build evidence recomputation');
  }
  return captureBuildEvidence(
    repoPath,
    sourceState,
    expected.buildInputs.map(({ name, path }) => ({ name, path })),
    toolchains,
  );
}

export function buildEvidenceMatches(expected: BuildEvidence, actual: BuildEvidence): boolean {
  return expected.evidenceDigest === actual.evidenceDigest
    && expected.sourceStateId === actual.sourceStateId;
}

/**
 * Advisory repository-harness contract.
 *
 * Repository harnesses coordinate local ownership and collect evidence. They do
 * not grant Ruflo policy capabilities. Existing harnesses can implement only
 * `describe`; omitted operations remain unavailable and the descriptor
 * normalizes to observe-only compatibility mode.
 */

import type { ExactSourceState } from './repository-state.js';
import type { BuildEvidence } from './build-evidence.js';

export type HarnessMode = 'observe' | 'enforce';
export type HarnessCapability =
  | 'sessions'
  | 'leases'
  | 'lease-fencing'
  | 'messages'
  | 'message-acknowledgement'
  | 'run-evidence'
  | 'exact-source-state'
  | 'release-decisions';

interface HarnessDescriptorBase {
  contractVersion: 1;
  harnessId: string;
}

export interface InMemoryReferenceHarnessDescriptor extends HarnessDescriptorBase {
  mode: 'observe';
  capabilities: readonly Exclude<HarnessCapability, 'release-decisions'>[];
  advisory: true;
  assurance: 'in-memory-reference';
}

export interface ExternalAuthorityHarnessDescriptor extends HarnessDescriptorBase {
  mode: HarnessMode;
  capabilities: readonly HarnessCapability[];
  advisory: false;
  assurance: 'external-authority';
}

export type HarnessDescriptor =
  | InMemoryReferenceHarnessDescriptor
  | ExternalAuthorityHarnessDescriptor;

/** Shape accepted from pre-contract local harnesses. */
export interface LegacyHarnessDescriptor {
  harnessId?: string;
  name?: string;
  mode?: HarnessMode;
  capabilities?: readonly string[];
}

export interface StartSessionRequest {
  sessionId: string;
  workloadId: string;
  repositoryId: string;
  worktreeId: string;
  readOnly: boolean;
}

export interface HarnessSession {
  sessionId: string;
  workloadId: string;
  repositoryId: string;
  worktreeId: string;
  startedAt: string;
}

export interface LeaseRequest {
  sessionId: string;
  repositoryId: string;
  worktreeId: string;
  kind: 'path' | 'resource';
  scopes: readonly string[];
  ttlMs: number;
}

export interface FencedLease {
  leaseId: string;
  repositoryId: string;
  sessionId: string;
  workloadId: string;
  worktreeId: string;
  kind: 'path' | 'resource';
  scopes: readonly string[];
  /** Decimal strings avoid losing 64-bit epochs when receipts cross JSON. */
  epoch: string;
  version: string;
  issuedAt: string;
  expiresAt: string;
  advisory: boolean;
}

export interface HarnessMessage {
  messageId: string;
  issuer: string;
  audience: string;
  correlationId?: string;
  causationId?: string;
  sequence: string;
  expiresAt?: string;
  contentDigest: string;
  content: unknown;
}

export interface MessageReceipt {
  messageId: string;
  acceptedAt: string;
  duplicate: boolean;
}

export interface RunEvidence {
  executionId: string;
  sessionId: string;
  workloadId: string;
  sourceState: ExactSourceState;
  /** Optional for legacy/debug runs; release policy may require it. */
  buildEvidence?: BuildEvidence;
  commandDigest: string;
  scope: string;
  profile: 'focused' | 'integration' | 'release';
  startedAt: string;
  completedAt: string;
  exitCode: number;
  evidenceDigest: string;
  policyReceiptId?: string;
  leaseEpochs?: Readonly<Record<string, string>>;
}

export interface RunReceipt extends RunEvidence {
  receiptId: string;
  recordedAt: string;
}

export interface ReleaseRequest {
  repositoryId: string;
  sourceStateId: string;
  artifactDigest: string;
  runReceiptIds: readonly string[];
  /** Optional for compatibility; enforce-mode release policy may require it. */
  buildEvidence?: BuildEvidence;
  capabilityId?: string;
}

export interface ReleaseDecision {
  allowed: boolean;
  dryRun: boolean;
  reason: string;
  policyReceiptId?: string;
}

/**
 * Progressive adapter surface. Optional methods preserve compatibility with
 * local harnesses that predate sessions, fencing, durable messages, or exact
 * source-state receipts. Callers must feature-detect every optional operation.
 */
export interface RepositoryHarnessAdapter {
  describe(): Promise<HarnessDescriptor | LegacyHarnessDescriptor>;
  start?(request: StartSessionRequest): Promise<HarnessSession>;
  acquire?(request: LeaseRequest): Promise<FencedLease>;
  renew?(lease: FencedLease): Promise<FencedLease>;
  release?(lease: FencedLease): Promise<void>;
  send?(message: HarnessMessage): Promise<MessageReceipt>;
  receive?(cursor?: string): AsyncIterable<HarnessMessage>;
  acknowledge?(messageId: string): Promise<void>;
  recordRun?(run: RunEvidence): Promise<RunReceipt>;
  authorizeRelease?(request: ReleaseRequest): Promise<ReleaseDecision>;
  end?(sessionId: string): Promise<void>;
}

const CAPABILITIES = new Set<HarnessCapability>([
  'sessions',
  'leases',
  'lease-fencing',
  'messages',
  'message-acknowledgement',
  'run-evidence',
  'exact-source-state',
  'release-decisions',
]);

/**
 * Convert an older descriptor to the safe v1 reference baseline.
 *
 * Unknown and authority-bearing capabilities are ignored. A legacy descriptor
 * can never self-assert enforce or release authority through this compatibility
 * function. A separately verified external adapter is required for that.
 */
export function normalizeHarnessDescriptor(
  input: HarnessDescriptor | LegacyHarnessDescriptor,
): InMemoryReferenceHarnessDescriptor {
  const harnessId = input.harnessId ?? ('name' in input ? input.name : undefined);
  if (typeof harnessId !== 'string' || harnessId.trim().length === 0) {
    throw new Error('repository harness descriptor requires a non-empty harnessId');
  }

  const requested = Array.isArray(input.capabilities) ? input.capabilities : [];
  const capabilities: Array<Exclude<HarnessCapability, 'release-decisions'>> = [...new Set(
    requested.filter((value): value is HarnessCapability => (
      CAPABILITIES.has(value as HarnessCapability)
      && value !== 'release-decisions'
    )),
  )] as Array<Exclude<HarnessCapability, 'release-decisions'>>;
  capabilities.sort();

  return {
    contractVersion: 1,
    harnessId: harnessId.trim(),
    mode: 'observe',
    capabilities,
    advisory: true,
    assurance: 'in-memory-reference',
  };
}

import { randomUUID } from 'node:crypto';
import type { FencedLease, LeaseRequest } from './contract.js';
import { portableCaseFold } from './portable-case-fold.js';
import { parseCanonicalUnsigned } from './unsigned-integer.js';

export interface FencedLeaseRequest extends LeaseRequest {
  workloadId: string;
}

export type InMemoryFenceRefusal =
  | 'invalid-request'
  | 'scope-conflict'
  | 'stale-fence'
  | 'expired-fence'
  | 'unknown-lease';

export class InMemoryFenceReferenceError extends Error {
  constructor(readonly reason: InMemoryFenceRefusal, detail: string) {
    super(detail);
  }
}

interface StoredLease {
  lease: FencedLease;
  expiresAtMs: number;
}

function compare(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function text(value: string, label: string): string {
  const result = value.trim();
  if (!result) throw new InMemoryFenceReferenceError('invalid-request', `${label} must be non-empty`);
  return result;
}

function normalizeScope(kind: LeaseRequest['kind'], value: string): string {
  const scope = text(value, 'lease scope');
  if (scope.startsWith('-') || scope.includes('\\') || scope !== scope.normalize('NFC')) {
    throw new InMemoryFenceReferenceError('invalid-request', `unsafe lease scope: ${value}`);
  }
  if (kind === 'resource') {
    if (scope.includes('/') || scope === '.' || scope === '..') {
      throw new InMemoryFenceReferenceError('invalid-request', `invalid named resource: ${value}`);
    }
    return scope;
  }
  if (
    scope.startsWith('/')
    || scope.split('/').some((part) => !part || part === '.' || part === '..')
  ) {
    throw new InMemoryFenceReferenceError('invalid-request', `invalid path scope: ${value}`);
  }
  return scope;
}

function overlaps(kind: LeaseRequest['kind'], left: string, right: string): boolean {
  if (kind === 'resource') return left === right;
  const foldedLeft = portableCaseFold(left);
  const foldedRight = portableCaseFold(right);
  return foldedLeft === foldedRight
    || foldedLeft.startsWith(`${foldedRight}/`)
    || foldedRight.startsWith(`${foldedLeft}/`);
}

function sameStrings(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((value, index) => value === right[index]);
}

function copyLease(lease: FencedLease): FencedLease {
  return { ...lease, scopes: [...lease.scopes] };
}

/**
 * Unsigned, non-durable, single-process conformance reference.
 *
 * JavaScript executes each method without an await boundary, so compare,
 * validate, and mutate form one atomic critical section. Distributed adapters
 * must provide the same semantics with a CP store. This class cannot satisfy an
 * enforce-mode policy decision or authorize release/external side effects.
 */
export class InMemoryFencedLeaseReference {
  /** This model is local, unsigned, and never an enforce-mode policy authority. */
  readonly referenceOnly = true;
  private readonly leases = new Map<string, StoredLease>();
  private readonly repositoryEpoch = new Map<string, bigint>();

  constructor(private readonly now: () => number = Date.now) {}

  acquire(request: FencedLeaseRequest): FencedLease {
    const repositoryId = text(request.repositoryId, 'repositoryId');
    const scopes = [...new Set(request.scopes.map((scope) => normalizeScope(request.kind, scope)))]
      .sort(compare);
    if (!scopes.length || !Number.isSafeInteger(request.ttlMs) || request.ttlMs <= 0) {
      throw new InMemoryFenceReferenceError('invalid-request', 'lease requires scopes and a positive safe ttlMs');
    }
    const now = this.now();
    this.pruneExpired(now);
    for (const stored of this.leases.values()) {
      const current = stored.lease;
      if (current.repositoryId !== repositoryId || current.kind !== request.kind) continue;
      if (current.scopes.some((held) => scopes.some((wanted) => overlaps(request.kind, held, wanted)))) {
        throw new InMemoryFenceReferenceError(
          'scope-conflict',
          `scope conflicts with active lease ${current.leaseId}`,
        );
      }
    }

    const epoch = (this.repositoryEpoch.get(repositoryId) ?? 0n) + 1n;
    this.repositoryEpoch.set(repositoryId, epoch);
    const expiresAtMs = now + request.ttlMs;
    if (!Number.isSafeInteger(expiresAtMs)) {
      throw new InMemoryFenceReferenceError('invalid-request', 'lease expiry exceeds safe timestamp range');
    }
    const lease: FencedLease = {
      leaseId: `lease-${randomUUID()}`,
      repositoryId,
      sessionId: text(request.sessionId, 'sessionId'),
      workloadId: text(request.workloadId, 'workloadId'),
      worktreeId: text(request.worktreeId, 'worktreeId'),
      kind: request.kind,
      scopes,
      epoch: epoch.toString(),
      version: '1',
      issuedAt: new Date(now).toISOString(),
      expiresAt: new Date(expiresAtMs).toISOString(),
      advisory: true,
    };
    this.leases.set(lease.leaseId, { lease, expiresAtMs });
    return copyLease(lease);
  }

  renew(presented: FencedLease, ttlMs: number): FencedLease {
    if (!Number.isSafeInteger(ttlMs) || ttlMs <= 0) {
      throw new InMemoryFenceReferenceError('invalid-request', 'renewal requires a positive safe ttlMs');
    }
    const stored = this.assertStoredFence(presented);
    const now = this.now();
    if (stored.expiresAtMs <= now) {
      this.leases.delete(presented.leaseId);
      throw new InMemoryFenceReferenceError('expired-fence', `lease ${presented.leaseId} expired`);
    }
    const expiresAtMs = now + ttlMs;
    if (!Number.isSafeInteger(expiresAtMs)) {
      throw new InMemoryFenceReferenceError('invalid-request', 'lease expiry exceeds safe timestamp range');
    }
    const lease: FencedLease = {
      ...stored.lease,
      version: (parseCanonicalUnsigned(stored.lease.version, 'lease version') + 1n).toString(),
      expiresAt: new Date(expiresAtMs).toISOString(),
      scopes: [...stored.lease.scopes],
    };
    this.leases.set(lease.leaseId, { lease, expiresAtMs });
    return copyLease(lease);
  }

  release(presented: FencedLease): void {
    this.assertCurrentFence(presented);
    this.leases.delete(presented.leaseId);
  }

  assertCurrentFence(presented: FencedLease): void {
    const stored = this.assertStoredFence(presented);
    if (stored.expiresAtMs <= this.now()) {
      this.leases.delete(presented.leaseId);
      throw new InMemoryFenceReferenceError('expired-fence', `lease ${presented.leaseId} expired`);
    }
  }

  current(repositoryId?: string): FencedLease[] {
    this.pruneExpired(this.now());
    return [...this.leases.values()]
      .map(({ lease }) => lease)
      .filter((lease) => repositoryId === undefined || lease.repositoryId === repositoryId)
      .sort((left, right) => compare(left.leaseId, right.leaseId))
      .map(copyLease);
  }

  private assertStoredFence(presented: FencedLease): StoredLease {
    const stored = this.leases.get(presented.leaseId);
    if (!stored) throw new InMemoryFenceReferenceError('unknown-lease', `unknown lease ${presented.leaseId}`);
    const current = stored.lease;
    if (
      current.repositoryId !== presented.repositoryId
      || current.sessionId !== presented.sessionId
      || current.workloadId !== presented.workloadId
      || current.worktreeId !== presented.worktreeId
      || current.kind !== presented.kind
      || !sameStrings(current.scopes, presented.scopes)
      || current.epoch !== presented.epoch
      || current.version !== presented.version
    ) {
      throw new InMemoryFenceReferenceError('stale-fence', `stale or altered fence ${presented.leaseId}`);
    }
    return stored;
  }

  private pruneExpired(now: number): void {
    for (const [leaseId, stored] of this.leases) {
      if (stored.expiresAtMs <= now) this.leases.delete(leaseId);
    }
  }
}

import { createHash } from 'node:crypto';
import type { HarnessMessage, MessageReceipt } from './contract.js';
import { canonicalJson } from './repository-state.js';
import { parseCanonicalUnsigned } from './unsigned-integer.js';

export interface InMemoryInboxRecord {
  cursor: string;
  message: HarnessMessage;
  receivedAt: string;
  acknowledgedAt?: string;
}

export interface InMemoryQuarantinedMessage {
  issuer: string;
  messageId: string;
  reason: 'content-digest-mismatch' | 'message-id-content-conflict';
  quarantinedAt: string;
}

function sha256(value: string): string {
  return `sha256:${createHash('sha256').update(value).digest('hex')}`;
}

function clone<T>(value: T): T {
  return structuredClone(value);
}

export function harnessMessageContentDigest(content: unknown): string {
  return sha256(canonicalJson(content));
}

function lengthFrame(values: readonly string[]): string {
  return values.map((value) => `${Buffer.byteLength(value, 'utf8')}:${value}`).join('|');
}

/** Collision-safe local map key; the unhashed material is byte-length framed. */
export function inMemoryInboxIdentityKey(issuer: string, messageId: string): string {
  return sha256(lengthFrame([issuer, messageId]));
}

/**
 * Unsigned, non-durable in-memory model of inbox semantics.
 *
 * It retains unacknowledged records, resumes by monotonic cursor, deduplicates
 * exact retries, and quarantines an issuer reusing a message ID with different
 * content. Process exit loses all state; this class is never an enforce-mode
 * transport or authority. Durable adapters may use it only as a conformance
 * reference.
 */
export class InMemoryInboxReference {
  readonly referenceOnly = true;
  private readonly records: InMemoryInboxRecord[] = [];
  private readonly byIdentity = new Map<string, {
    issuer: string;
    messageId: string;
    envelopeDigest: string;
    record: InMemoryInboxRecord;
  }>();
  private readonly quarantined: InMemoryQuarantinedMessage[] = [];
  private nextCursor = 1n;

  constructor(private readonly now: () => number = Date.now) {}

  send(message: HarnessMessage): MessageReceipt {
    if (!message.messageId.trim() || !message.issuer.trim() || !message.audience.trim()) {
      throw new Error('message ID, issuer, and audience are required');
    }
    const identity = inMemoryInboxIdentityKey(message.issuer, message.messageId);
    const receivedAt = new Date(this.now()).toISOString();
    let suppliedDigest: string;
    try {
      suppliedDigest = harnessMessageContentDigest(message.content);
    } catch {
      this.quarantine(message, 'content-digest-mismatch', receivedAt);
      throw new Error('message content is not canonical JSON');
    }
    if (suppliedDigest !== message.contentDigest) {
      this.quarantine(message, 'content-digest-mismatch', receivedAt);
      throw new Error('message contentDigest does not match canonical content');
    }
    try {
      parseCanonicalUnsigned(message.sequence, 'message sequence');
    } catch {
      throw new Error('message sequence must be a canonical unsigned decimal integer');
    }
    if (message.expiresAt !== undefined && !Number.isFinite(Date.parse(message.expiresAt))) {
      throw new Error('message expiresAt must be an ISO timestamp');
    }

    const envelopeDigest = sha256(canonicalJson(message));
    const prior = this.byIdentity.get(identity);
    if (prior) {
      if (prior.issuer !== message.issuer || prior.messageId !== message.messageId) {
        throw new Error('inbox identity hash collision');
      }
      if (prior.envelopeDigest !== envelopeDigest) {
        this.quarantine(message, 'message-id-content-conflict', receivedAt);
        throw new Error('message ID was reused with different content');
      }
      return { messageId: message.messageId, acceptedAt: prior.record.receivedAt, duplicate: true };
    }

    const record: InMemoryInboxRecord = {
      cursor: (this.nextCursor++).toString(),
      message: clone(message),
      receivedAt,
    };
    this.records.push(record);
    this.byIdentity.set(identity, {
      issuer: message.issuer,
      messageId: message.messageId,
      envelopeDigest,
      record,
    });
    return { messageId: message.messageId, acceptedAt: receivedAt, duplicate: false };
  }

  async *receive(audience: string, cursor = '0'): AsyncIterable<HarnessMessage> {
    const after = this.parseCursor(cursor);
    const now = this.now();
    for (const record of this.records) {
      if (
        BigInt(record.cursor) > after
        && record.message.audience === audience
        && (record.message.expiresAt === undefined || Date.parse(record.message.expiresAt) > now)
      ) {
        yield clone(record.message);
      }
    }
  }

  acknowledge(audience: string, messageId: string, issuer?: string): void {
    const matches = this.records.filter(
      (candidate) => candidate.message.audience === audience
        && candidate.message.messageId === messageId
        && (issuer === undefined || candidate.message.issuer === issuer),
    );
    if (!matches.length) throw new Error(`unknown inbox message ${messageId} for ${audience}`);
    if (matches.length > 1) throw new Error(`ambiguous inbox message ${messageId}; issuer is required`);
    const record = matches[0]!;
    if (record.acknowledgedAt === undefined) record.acknowledgedAt = new Date(this.now()).toISOString();
  }

  pending(audience: string): InMemoryInboxRecord[] {
    return this.records
      .filter((record) => record.message.audience === audience && record.acknowledgedAt === undefined)
      .map(clone);
  }

  quarantineRecords(): InMemoryQuarantinedMessage[] {
    return this.quarantined.map(clone);
  }

  private parseCursor(cursor: string): bigint {
    try {
      return parseCanonicalUnsigned(cursor, 'inbox cursor');
    } catch {
      throw new Error('inbox cursor must be a non-negative decimal integer');
    }
  }

  private quarantine(
    message: HarnessMessage,
    reason: InMemoryQuarantinedMessage['reason'],
    quarantinedAt: string,
  ): void {
    this.quarantined.push({
      issuer: message.issuer,
      messageId: message.messageId,
      reason,
      quarantinedAt,
    });
  }
}

import { createHash } from 'node:crypto';
import type { RunEvidence, RunReceipt } from './contract.js';
import { canonicalJson } from './repository-state.js';

const DIGEST = /^sha256:[0-9a-f]{64}$/;

function sha256(value: string): string {
  return `sha256:${createHash('sha256').update(value).digest('hex')}`;
}

function copy<T>(value: T): T {
  return structuredClone(value);
}

function timestamp(value: string, label: string): number {
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed)) throw new Error(`${label} must be an ISO timestamp`);
  return parsed;
}

function validateRun(run: RunEvidence): void {
  if (!run.executionId.trim() || !run.sessionId.trim() || !run.workloadId.trim()) {
    throw new Error('run execution, session, and workload identity are required');
  }
  if (!DIGEST.test(run.sourceState.sourceStateId)) throw new Error('run sourceStateId is invalid');
  if (!DIGEST.test(run.commandDigest) || !DIGEST.test(run.evidenceDigest)) {
    throw new Error('run command and evidence digests must be canonical sha256 values');
  }
  if (!Number.isSafeInteger(run.exitCode)) throw new Error('run exitCode must be a safe integer');
  const started = timestamp(run.startedAt, 'startedAt');
  const completed = timestamp(run.completedAt, 'completedAt');
  if (completed < started) throw new Error('run completedAt precedes startedAt');
  if (
    run.buildEvidence !== undefined
    && run.buildEvidence.sourceStateId !== run.sourceState.sourceStateId
  ) {
    throw new Error('build evidence belongs to a different source state');
  }
}

/**
 * Unsigned, non-durable, content-addressed in-memory conformance ledger.
 *
 * Exact retries converge on one receipt. Reusing an execution ID with changed
 * evidence is refused rather than rewriting history. These receipts are local
 * debugging evidence and cannot authorize enforce mode or release.
 */
export class InMemoryRunReceiptReference {
  readonly referenceOnly = true;
  private readonly receipts = new Map<string, RunReceipt>();
  private readonly executionReceipts = new Map<string, string>();

  constructor(private readonly now: () => number = Date.now) {}

  recordRun(run: RunEvidence): RunReceipt {
    validateRun(run);
    const canonical = canonicalJson(run);
    const receiptId = sha256(canonical);
    const existingExecution = this.executionReceipts.get(run.executionId);
    if (existingExecution !== undefined && existingExecution !== receiptId) {
      throw new Error(`executionId ${run.executionId} already records different evidence`);
    }
    const existing = this.receipts.get(receiptId);
    if (existing) return copy(existing);

    const receipt: RunReceipt = {
      ...copy(run),
      receiptId,
      recordedAt: new Date(this.now()).toISOString(),
    };
    this.receipts.set(receiptId, receipt);
    this.executionReceipts.set(run.executionId, receiptId);
    return copy(receipt);
  }

  get(receiptId: string): RunReceipt | undefined {
    const receipt = this.receipts.get(receiptId);
    return receipt ? copy(receipt) : undefined;
  }

  all(): RunReceipt[] {
    return [...this.receipts.values()].map(copy);
  }
}

export * from './build-evidence.js';
export * from './contract.js';
export * from './in-memory-inbox-reference.js';
export * from './in-memory-fenced-lease-reference.js';
export * from './in-memory-run-receipt-reference.js';
export * from './portable-case-fold.js';
export * from './repository-state.js';
export * from './unsigned-integer.js';

/**
 * Conservative, deterministic case-fold key for cross-platform collision
 * refusal. Upper-then-lower catches multi-code-point folds such as ß -> ss and
 * final sigma -> sigma. NFKC intentionally over-rejects compatibility aliases;
 * it is never used to rewrite a repository path.
 */
export function portableCaseFold(value: string): string {
  return value.normalize('NFKC').toUpperCase().toLowerCase().normalize('NFC');
}

import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  lstatSync,
  readFileSync,
  readlinkSync,
  realpathSync,
} from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { portableCaseFold } from './portable-case-fold.js';

const SHA256_PREFIX = 'sha256:';
const MAX_GIT_BUFFER = 128 * 1024 * 1024;

export interface RepositoryIdentity {
  repositoryId: string;
  canonicalRemote?: string;
  gitCommonDirId: string;
  rootTreeId: string;
}

export interface ContentDigest {
  algorithm: 'sha256';
  digest: string;
  bytes: number;
}

export interface UntrackedFileIdentity {
  path: string;
  kind: 'file' | 'symlink';
  mode: number;
  bytes: number;
  digest: string;
}

export interface UntrackedManifest {
  digest: string;
  entries: readonly UntrackedFileIdentity[];
}

export interface SubmoduleState {
  path: string;
  initialized: boolean;
  expectedCommit: string;
  commit?: string;
  trackedPatch: ContentDigest;
  untrackedManifest: UntrackedManifest;
  submodules: readonly SubmoduleState[];
}

interface SourceStateBase {
  version: 1;
  /** Git-visible state excludes ignored build inputs and installed toolchains. */
  scope: 'git-visible';
  repository: RepositoryIdentity;
  baseCommit: string;
  treeId: string;
  sourceStateId: string;
}

export interface CleanSourceState extends SourceStateBase {
  kind: 'clean';
  clean: true;
}

export interface DirtySourceState extends SourceStateBase {
  kind: 'dirty';
  clean: false;
  trackedPatch: ContentDigest;
  untrackedManifest: UntrackedManifest;
  submodules: readonly SubmoduleState[];
}

export type ExactSourceState = CleanSourceState | DirtySourceState;

interface ContentState {
  baseCommit: string;
  treeId: string;
  trackedPatch: ContentDigest;
  untrackedManifest: UntrackedManifest;
  submodules: readonly SubmoduleState[];
}

function digest(value: string | Buffer): string {
  return `${SHA256_PREFIX}${createHash('sha256').update(value).digest('hex')}`;
}

function assertUnicodeScalarString(value: string): void {
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) {
        throw new Error('canonical JSON does not support lone UTF-16 surrogates');
      }
      index += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      throw new Error('canonical JSON does not support lone UTF-16 surrogates');
    }
  }
}

function codeUnitCompare(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

/** Recursive, locale-independent canonical JSON for JSON-safe contract values. */
export function canonicalJson(value: unknown): string {
  const ancestors = new Set<object>();
  const encode = (item: unknown): string => {
    if (item === null || typeof item === 'boolean') return JSON.stringify(item);
    if (typeof item === 'string') {
      assertUnicodeScalarString(item);
      return JSON.stringify(item);
    }
    if (typeof item === 'number') {
      if (
        !Number.isFinite(item)
        || Object.is(item, -0)
        || (Number.isInteger(item) && !Number.isSafeInteger(item))
      ) {
        throw new Error('canonical JSON requires finite, safe, non-negative-zero numbers');
      }
      return JSON.stringify(item);
    }
    if (item === undefined) throw new Error('canonical JSON does not support undefined');
    if (typeof item !== 'object') {
      throw new Error(`canonical JSON does not support ${typeof item}`);
    }
    if (ancestors.has(item)) throw new Error('canonical JSON does not support cycles');
    ancestors.add(item);
    try {
      if (Array.isArray(item)) return `[${item.map(encode).join(',')}]`;
      const prototype = Object.getPrototypeOf(item);
      if (prototype !== Object.prototype && prototype !== null) {
        throw new Error('canonical JSON supports only arrays and plain objects');
      }
      const entries = Object.entries(item as Record<string, unknown>)
        .sort(([left], [right]) => codeUnitCompare(left, right));
      return `{${entries.map(([key, child]) => {
        assertUnicodeScalarString(key);
        return `${JSON.stringify(key)}:${encode(child)}`;
      }).join(',')}}`;
    } finally {
      ancestors.delete(item);
    }
  };
  return encode(value);
}

function gitBuffer(repoRoot: string, args: readonly string[]): Buffer {
  return execFileSync('git', ['-C', repoRoot, ...args], {
    encoding: 'buffer',
    stdio: ['ignore', 'pipe', 'pipe'],
    maxBuffer: MAX_GIT_BUFFER,
  });
}

function gitText(repoRoot: string, args: readonly string[]): string {
  return gitBuffer(repoRoot, args).toString('utf8').trim();
}

function optionalGitText(repoRoot: string, args: readonly string[]): string | undefined {
  try {
    const value = gitText(repoRoot, args);
    return value.length > 0 ? value : undefined;
  } catch {
    return undefined;
  }
}

function splitNul(output: Buffer): Buffer[] {
  const records: Buffer[] = [];
  let start = 0;
  for (let index = 0; index < output.length; index += 1) {
    if (output[index] !== 0) continue;
    if (index > start) records.push(output.subarray(start, index));
    start = index + 1;
  }
  if (start !== output.length) throw new Error('Git returned a non-NUL-terminated path list');
  return records;
}

function decodeGitPath(bytes: Buffer): string {
  const path = bytes.toString('utf8');
  if (!Buffer.from(path, 'utf8').equals(bytes)) {
    throw new Error('Git path is not valid round-trip UTF-8');
  }
  assertUnicodeScalarString(path);
  if (path !== path.normalize('NFC')) {
    throw new Error(`Git path is not NFC-normalized: ${path}`);
  }
  return normalizeRelativePath(path);
}

function normalizeRelativePath(path: string): string {
  assertUnicodeScalarString(path);
  if (path.includes('\\')) throw new Error(`ambiguous repository path separator: ${path}`);
  const normalized = path.normalize('NFC');
  if (
    normalized.length === 0
    || isAbsolute(normalized)
    || normalized.startsWith('-')
    || normalized.split('/').some((part) => part === '' || part === '.' || part === '..')
  ) {
    throw new Error(`unsafe repository-relative path: ${path}`);
  }
  return normalized;
}

function assertNoPathCollisions(paths: readonly string[]): void {
  const exact = new Set<string>();
  const folded = new Map<string, string>();
  for (const path of paths) {
    if (exact.has(path)) throw new Error(`duplicate repository path: ${path}`);
    exact.add(path);
    const key = portableCaseFold(path);
    const prior = folded.get(key);
    if (prior !== undefined && prior !== path) {
      throw new Error(`case-fold repository path collision: ${prior} and ${path}`);
    }
    folded.set(key, path);
  }
}

function repositoryPaths(repoRoot: string, includeUntracked: boolean): readonly string[] {
  const tracked = splitNul(gitBuffer(repoRoot, ['ls-files', '-z'])).map(decodeGitPath);
  const untracked = includeUntracked
    ? splitNul(gitBuffer(repoRoot, ['ls-files', '--others', '--exclude-standard', '-z'])).map(decodeGitPath)
    : [];
  const paths = [...tracked, ...untracked].sort(codeUnitCompare);
  assertNoPathCollisions(paths);
  return paths;
}

function assertInsideRepository(repoRoot: string, candidate: string): void {
  const rel = relative(repoRoot, candidate);
  if (rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)) {
    throw new Error(`repository path escapes root: ${candidate}`);
  }
}

function contentDigest(content: Buffer): ContentDigest {
  return { algorithm: 'sha256', digest: digest(content), bytes: content.byteLength };
}

function untrackedManifest(repoRoot: string): UntrackedManifest {
  const output = gitBuffer(repoRoot, ['ls-files', '--others', '--exclude-standard', '-z']);
  const paths = splitNul(output).map(decodeGitPath).sort(codeUnitCompare);
  assertNoPathCollisions(paths);
  const entries = paths.map((path): UntrackedFileIdentity => {
    const absolute = resolve(repoRoot, path);
    assertInsideRepository(repoRoot, absolute);
    const before = lstatSync(absolute);
    let kind: UntrackedFileIdentity['kind'];
    let content: Buffer;
    if (before.isSymbolicLink()) {
      kind = 'symlink';
      content = Buffer.from(readlinkSync(absolute), 'utf8');
    } else if (before.isFile()) {
      kind = 'file';
      content = readFileSync(absolute);
    } else {
      throw new Error(`unsupported untracked repository entry: ${path}`);
    }
    const after = lstatSync(absolute);
    if (
      before.mode !== after.mode
      || before.size !== after.size
      || before.mtimeMs !== after.mtimeMs
      || before.ino !== after.ino
    ) {
      throw new Error(`repository changed while hashing untracked entry: ${path}`);
    }
    return {
      path,
      kind,
      mode: before.mode & 0o7777,
      bytes: content.byteLength,
      digest: digest(content),
    };
  });
  return { digest: digest(canonicalJson(entries)), entries };
}

function trackedPatch(repoRoot: string): ContentDigest {
  return contentDigest(gitBuffer(repoRoot, [
    'diff',
    '--binary',
    '--full-index',
    '--no-ext-diff',
    'HEAD',
    '--',
  ]));
}

function submoduleStates(repoRoot: string): readonly SubmoduleState[] {
  const staged = splitNul(gitBuffer(repoRoot, ['ls-files', '--stage', '-z']));
  const submodules = staged.flatMap((entry): Array<{ path: string; commit: string }> => {
    const tab = entry.indexOf(0x09);
    if (tab < 0) throw new Error('malformed Git index record');
    const metadata = entry.subarray(0, tab).toString('ascii');
    const match = /^160000 ([0-9a-f]+) [0-3]$/.exec(metadata);
    return match?.[1]
      ? [{ path: decodeGitPath(entry.subarray(tab + 1)), commit: match[1] }]
      : [];
  });
  assertNoPathCollisions(submodules.map(({ path }) => path));

  return submodules.map(({ path, commit }): SubmoduleState => {
    const absolute = resolve(repoRoot, path);
    assertInsideRepository(repoRoot, absolute);
    const actualCommit = optionalGitText(absolute, ['rev-parse', '--verify', 'HEAD']);
    if (!actualCommit) {
      return {
        path,
        initialized: false,
        expectedCommit: commit,
        trackedPatch: contentDigest(Buffer.alloc(0)),
        untrackedManifest: { digest: digest('[]'), entries: [] },
        submodules: [],
      };
    }
    repositoryPaths(absolute, true);
    return {
      path,
      initialized: true,
      expectedCommit: commit,
      commit: actualCommit,
      trackedPatch: trackedPatch(absolute),
      untrackedManifest: untrackedManifest(absolute),
      submodules: submoduleStates(absolute),
    };
  });
}

function captureContentState(repoRoot: string): ContentState {
  const baseCommit = gitText(repoRoot, ['rev-parse', '--verify', 'HEAD']);
  const treeId = gitText(repoRoot, ['rev-parse', '--verify', 'HEAD^{tree}']);
  return {
    baseCommit,
    treeId,
    trackedPatch: trackedPatch(repoRoot),
    untrackedManifest: untrackedManifest(repoRoot),
    submodules: submoduleStates(repoRoot),
  };
}

function canonicalizeRemote(remote: string): string {
  const trimmed = remote.trim();
  const scp = /^([^/@:]+@)?([^/:]+):(.+)$/.exec(trimmed);
  if (scp?.[2] && scp[3] && !trimmed.includes('://')) {
    return `ssh://${scp[2].toLowerCase()}/${scp[3].replace(/^\/+|\/+$/g, '').replace(/\.git$/i, '')}`;
  }
  try {
    const url = new URL(trimmed);
    url.username = '';
    url.password = '';
    url.hostname = url.hostname.toLowerCase();
    url.pathname = url.pathname.replace(/\.git$/i, '').replace(/\/+$/g, '');
    url.hash = '';
    url.search = '';
    return url.toString().replace(/\/$/, '');
  } catch {
    return trimmed.replace(/\.git$/i, '').replace(/\/+$/g, '');
  }
}

function repositoryIdentity(repoRoot: string): RepositoryIdentity {
  const commonDirRaw = gitText(repoRoot, ['rev-parse', '--git-common-dir']);
  const commonDir = realpathSync(resolve(repoRoot, commonDirRaw));
  const canonicalRemoteRaw = optionalGitText(repoRoot, ['remote', 'get-url', 'origin']);
  const canonicalRemote = canonicalRemoteRaw ? canonicalizeRemote(canonicalRemoteRaw) : undefined;
  const rootCommits = gitText(repoRoot, ['rev-list', '--max-parents=0', 'HEAD']).split(/\s+/).sort();
  const rootTrees = rootCommits.map((commit) => gitText(repoRoot, ['rev-parse', `${commit}^{tree}`]));
  const rootTreeId = rootTrees.length === 1 ? rootTrees[0]! : digest(canonicalJson(rootTrees));
  const gitCommonDirId = digest(commonDir);
  const repositoryId = digest(canonicalJson({
    anchor: canonicalRemote ?? gitCommonDirId,
    rootTreeId,
  }));
  return {
    repositoryId,
    ...(canonicalRemote ? { canonicalRemote } : {}),
    gitCommonDirId,
    rootTreeId,
  };
}

function hasDirtySubmodule(submodule: SubmoduleState): boolean {
  return !submodule.initialized
    || submodule.commit !== submodule.expectedCommit
    || submodule.trackedPatch.bytes > 0
    || submodule.untrackedManifest.entries.length > 0
    || submodule.submodules.some(hasDirtySubmodule);
}

/**
 * Capture a stable, content-addressed Git source state.
 *
 * The collector performs two complete reads and refuses a moving worktree.
 * Ignored files are intentionally excluded because Git does not treat them as
 * repository source. Untracked symlinks bind their link target text without
 * following the target outside the worktree.
 */
export function captureRepositorySourceState(repoPath: string | URL): ExactSourceState {
  const requested = repoPath instanceof URL ? fileURLToPath(repoPath) : repoPath;
  const repoRoot = realpathSync(resolve(requested));
  const top = realpathSync(gitText(repoRoot, ['rev-parse', '--show-toplevel']));
  if (top !== repoRoot) throw new Error(`repoPath must be the Git top-level: ${top}`);

  const cleanStatus = (): Buffer => gitBuffer(repoRoot, [
    'status',
    '--porcelain=v1',
    '-z',
    '--untracked-files=all',
    '--ignore-submodules=none',
  ]);
  const initialStatus = cleanStatus();
  if (initialStatus.length === 0) {
    repositoryPaths(repoRoot, false);
    const baseCommit = gitText(repoRoot, ['rev-parse', '--verify', 'HEAD']);
    const treeId = gitText(repoRoot, ['rev-parse', '--verify', 'HEAD^{tree}']);
    if (cleanStatus().length !== 0 || gitText(repoRoot, ['rev-parse', '--verify', 'HEAD']) !== baseCommit) {
      throw new Error('repository changed while capturing exact source state');
    }
    const repository = repositoryIdentity(repoRoot);
    const identity = {
      version: 1,
      scope: 'git-visible',
      repositoryId: repository.repositoryId,
      commit: baseCommit,
      tree: treeId,
    };
    return {
      version: 1,
      scope: 'git-visible',
      kind: 'clean',
      clean: true,
      repository,
      baseCommit,
      treeId,
      sourceStateId: digest(canonicalJson(identity)),
    };
  }

  repositoryPaths(repoRoot, true);
  const first = captureContentState(repoRoot);
  const second = captureContentState(repoRoot);
  if (canonicalJson(first) !== canonicalJson(second)) {
    throw new Error('repository changed while capturing exact source state');
  }

  const repository = repositoryIdentity(repoRoot);
  const dirty = second.trackedPatch.bytes > 0
    || second.untrackedManifest.entries.length > 0
    || second.submodules.some(hasDirtySubmodule);

  if (!dirty) throw new Error('Git status reported changes that exact-state capture could not identify');

  const identity = {
    version: 1,
    scope: 'git-visible',
    repositoryId: repository.repositoryId,
    baseCommit: second.baseCommit,
    tree: second.treeId,
    trackedPatch: second.trackedPatch,
    untrackedManifest: second.untrackedManifest,
    submodules: second.submodules,
  };
  return {
    version: 1,
    scope: 'git-visible',
    kind: 'dirty',
    clean: false,
    repository,
    baseCommit: second.baseCommit,
    treeId: second.treeId,
    trackedPatch: second.trackedPatch,
    untrackedManifest: second.untrackedManifest,
    submodules: second.submodules,
    sourceStateId: digest(canonicalJson(identity)),
  };
}

export function sourceStateMatches(left: ExactSourceState, right: ExactSourceState): boolean {
  return left.sourceStateId === right.sourceStateId
    && left.repository.repositoryId === right.repository.repositoryId;
}

/** Release receipts default to the stronger committed-state requirement. */
export function isReleaseEligibleSourceState(state: ExactSourceState): state is CleanSourceState {
  return state.clean;
}

const CANONICAL_UNSIGNED = /^(?:0|[1-9][0-9]*)$/;
const MAX_UNSIGNED_64 = (1n << 64n) - 1n;

/** Parse a decimal unsigned integer without accepting aliases such as +1, 01, hex, or whitespace. */
export function parseCanonicalUnsigned(value: string, label: string): bigint {
  if (!CANONICAL_UNSIGNED.test(value)) {
    throw new Error(`${label} must be a canonical unsigned decimal integer`);
  }
  const parsed = BigInt(value);
  if (parsed > MAX_UNSIGNED_64) {
    throw new Error(`${label} exceeds unsigned 64-bit range`);
  }
  return parsed;
}

