import fs from 'fs-extra';
import path from 'path';
import { fileURLToPath } from 'node:url';
import type {
  CodexInitOptions,
  CodexInitResult,
  AgentsMdTemplate,
  BuiltInSkill,
} from './types.js';
import { generateAgentsMd } from './generators/agents-md.js';
import {
  BUILT_IN_SKILL_NAMES,
  generateSkillMd,
  generateBuiltInSkill,
} from './generators/skill-md.js';
