      'AGENTS.md',
      '.agents/config.toml',
      '.agents/README.md',
      '.codex/AGENTS.override.md',
      '.codex/config.toml',
      '.gitignore (updated)',
    ];

    const skills = options.skills ?? DEFAULT_SKILLS_BY_TEMPLATE[options.template ?? 'default'];
    for (const skill of skills) {
      files.push(`.agents/skills/${skill}/SKILL.md`);
