import { Command } from 'commander';
import chalk from 'chalk';
import path from 'node:path';
import {
  loadLoopState,
  requestLoopStop,
  resolveLoopPaths,
  runCodexLoop,
  type LoopState,
} from './index.js';

export function createLoopCommand(): Command {
  const loop = new Command('loop')
    .description('Run Codex in a bounded /loop-compatible iteration cycle');

  loop
    .command('run')
    .description('Start a Codex loop')
    .argument('[prompt...]', 'Prompt for Codex. Omit when using --command.')
    .option('-n, --name <name>', 'Loop name', 'default')
    .option('-p, --path <path>', 'Project path', process.cwd())
    .option('-i, --interval <seconds>', 'Seconds between iterations', '270')
    .option('-m, --max-iterations <count>', 'Maximum iterations; 0 means unbounded', '10')
    .option('--timeout <ms>', 'Per-iteration timeout in milliseconds', '1800000')
    .option('--until-file <path>', 'Stop when this file exists. Defaults to .codex/loop/<name>.complete')
    .option('--command <command>', 'Run a shell command each iteration instead of codex exec')
    .option('--codex-command <command>', 'Codex executable', 'codex')
    .option('--model <model>', 'Model passed to codex exec')
    .option('--sandbox <mode>', 'Sandbox passed to codex exec', 'workspace-write')
    .option('--no-skip-git-repo-check', 'Do not pass --skip-git-repo-check to codex exec')
    .option('--dry-run', 'Write planned state and print what would run without executing')
    .action(async (promptParts: string[], options) => {
      try {
        const prompt = promptParts.join(' ').trim();
        const state = await runCodexLoop({
          name: options.name,
          projectPath: options.path,
          prompt,
          command: options.command,
          codexCommand: options.codexCommand,
          model: options.model,
          sandbox: options.sandbox,
          skipGitRepoCheck: options.skipGitRepoCheck,
          intervalSeconds: parseInteger(options.interval, 270),
          maxIterations: parseInteger(options.maxIterations, 10),
          timeoutMs: parseInteger(options.timeout, 1_800_000),
          untilFile: options.untilFile,
          dryRun: options.dryRun,
          onEvent: event => {
            if (event.type === 'iteration-start') {
              console.log(chalk.cyan(`iteration ${event.state.iteration} starting`));
            } else if (event.type === 'iteration-complete') {
              console.log(chalk.gray(event.message ?? `iteration ${event.state.iteration} complete`));
            } else if (event.type === 'sleep') {
              console.log(chalk.gray(event.message));
            } else if (event.type === 'error') {
              console.log(chalk.red(event.message));
            }
          },
        });

        printState(state);
        if (state.status === 'failed') process.exitCode = 1;
      } catch (error) {
        console.error(chalk.red(error instanceof Error ? error.message : String(error)));
        process.exitCode = 1;
      }
    });

  loop
    .command('status')
    .description('Show loop state')
    .option('-n, --name <name>', 'Loop name', 'default')
    .option('-p, --path <path>', 'Project path', process.cwd())
    .option('--json', 'Print raw JSON state')
    .action(async (options) => {
      const projectPath = path.resolve(options.path);
      const state = await loadLoopState(projectPath, options.name);
      if (!state) {
        const paths = resolveLoopPaths(projectPath, options.name);
        console.log(chalk.yellow(`No loop state found at ${paths.statePath}`));
        return;
      }
      if (options.json) {
        console.log(JSON.stringify(state, null, 2));
        return;
      }
      printState(state);
    });

  loop
    .command('stop')
    .description('Request a running loop to stop after the current iteration')
    .option('-n, --name <name>', 'Loop name', 'default')
    .option('-p, --path <path>', 'Project path', process.cwd())
    .action(async (options) => {
      const projectPath = path.resolve(options.path);
      const paths = await requestLoopStop(projectPath, options.name);
      console.log(chalk.green(`Stop requested: ${paths.stopPath}`));
    });

  return loop;
}

function printState(state: LoopState): void {
  const color = state.status === 'failed'
    ? chalk.red
    : state.status === 'running'
      ? chalk.cyan
      : chalk.green;

  console.log(color(`Loop ${state.name}: ${state.status}`));
  console.log(chalk.gray(`  mode:       ${state.mode}`));
  console.log(chalk.gray(`  iteration:  ${state.iteration}/${state.maxIterations === 0 ? 'unbounded' : state.maxIterations}`));
  console.log(chalk.gray(`  interval:   ${state.intervalSeconds}s`));
  console.log(chalk.gray(`  until file: ${state.untilFile}`));
  if (state.lastExitCode !== undefined) {
    console.log(chalk.gray(`  last exit:  ${state.lastExitCode}`));
  }
  if (state.lastError) {
    console.log(chalk.red(`  last error: ${state.lastError.split('\n')[0]}`));
  }
}

function parseInteger(value: string | number | undefined, fallback: number): number {
  if (typeof value === 'number') return value;
  if (!value) return fallback;
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import fs from 'fs-extra';
import path from 'node:path';

export interface LoopRunOptions {
  name?: string;
  projectPath?: string;
  prompt?: string;
  command?: string;
  codexCommand?: string;
  model?: string;
  intervalSeconds?: number;
  maxIterations?: number;
  timeoutMs?: number;
  untilFile?: string;
  stateDir?: string;
  sandbox?: string;
  skipGitRepoCheck?: boolean;
  dryRun?: boolean;
  onEvent?: (event: LoopEvent) => void;
}

export interface LoopState {
  name: string;
  projectPath: string;
  mode: 'codex' | 'command';
  prompt?: string;
  command?: string;
  status: 'idle' | 'running' | 'stopping' | 'completed' | 'failed' | 'stopped';
  iteration: number;
  maxIterations: number;
  intervalSeconds: number;
  startedAt: string;
  updatedAt: string;
  lastExitCode?: number | null;
  lastOutput?: string;
  lastError?: string;
  untilFile: string;
}

export interface LoopEvent {
  type: 'start' | 'iteration-start' | 'iteration-complete' | 'sleep' | 'stop' | 'complete' | 'error' | 'dry-run';
  state: LoopState;
  message?: string;
}

export interface LoopPaths {
  stateDir: string;
  statePath: string;
  stopPath: string;
  completePath: string;
}

export interface LoopCommandResult {
  code: number | null;
  signal: NodeJS.Signals | null;
  stdout: string;
  stderr: string;
}

export function normalizeLoopName(name = 'default'): string {
  const normalized = name.trim().toLowerCase().replace(/[^a-z0-9_.-]+/g, '-').replace(/^-+|-+$/g, '');
  return normalized || 'default';
}

export function resolveLoopPaths(projectPath: string, name = 'default', stateDir?: string): LoopPaths {
  const safeName = normalizeLoopName(name);
  const resolvedStateDir = path.resolve(projectPath, stateDir ?? path.join('.codex', 'loop'));
  return {
    stateDir: resolvedStateDir,
    statePath: path.join(resolvedStateDir, `${safeName}.json`),
    stopPath: path.join(resolvedStateDir, `${safeName}.stop`),
    completePath: path.join(resolvedStateDir, `${safeName}.complete`),
  };
}

export async function loadLoopState(projectPath: string, name = 'default', stateDir?: string): Promise<LoopState | null> {
  const paths = resolveLoopPaths(projectPath, name, stateDir);
  if (!await fs.pathExists(paths.statePath)) return null;
  return await fs.readJson(paths.statePath) as LoopState;
}

export async function requestLoopStop(projectPath: string, name = 'default', stateDir?: string): Promise<LoopPaths> {
  const paths = resolveLoopPaths(projectPath, name, stateDir);
  await fs.ensureDir(paths.stateDir);
  await fs.writeFile(paths.stopPath, new Date().toISOString());

  const state = await loadLoopState(projectPath, name, stateDir);
  if (state && state.status === 'running') {
    state.status = 'stopping';
    state.updatedAt = new Date().toISOString();
    await saveLoopState(paths.statePath, state);
  }

  return paths;
}

export function buildCodexLoopPrompt(state: LoopState): string {
  const max = state.maxIterations > 0 ? state.maxIterations : 'unbounded';
  return [
    'You are running inside a Codex /loop-compatible iteration.',
    `Loop: ${state.name}`,
    `Iteration: ${state.iteration}/${max}`,
    `Project: ${state.projectPath}`,
    '',
    'Task:',
    state.prompt ?? '',
    '',
    'Work autonomously for this iteration. Make concrete progress, run relevant checks, and stop before broad unrelated refactors.',
    `If the task is fully complete, create this marker file: ${state.untilFile}`,
    'If more work remains, leave the marker absent so the next loop iteration can continue.',
  ].join('\n');
}

export async function runCodexLoop(options: LoopRunOptions = {}): Promise<LoopState> {
  const projectPath = path.resolve(options.projectPath ?? process.cwd());
  const name = normalizeLoopName(options.name);
  const paths = resolveLoopPaths(projectPath, name, options.stateDir);
  const intervalSeconds = clampInteger(options.intervalSeconds ?? 270, 0, 86_400);
  const maxIterations = clampInteger(options.maxIterations ?? 10, 0, 100_000);
  const timeoutMs = clampInteger(options.timeoutMs ?? 30 * 60_000, 1_000, 24 * 60 * 60_000);
  const untilFile = path.resolve(projectPath, options.untilFile ?? paths.completePath);
  const mode: LoopState['mode'] = options.command ? 'command' : 'codex';

  if (mode === 'codex' && !options.prompt?.trim()) {
    throw new Error('loop run requires a prompt unless --command is provided');
  }

  await fs.ensureDir(paths.stateDir);
  await fs.remove(paths.stopPath);

  const startedAt = new Date().toISOString();
  const state: LoopState = {
    name,
    projectPath,
    mode,
    status: 'running',
    iteration: 0,
    maxIterations,
    intervalSeconds,
    startedAt,
    updatedAt: startedAt,
    untilFile,
  };
  if (options.prompt !== undefined) state.prompt = options.prompt;
  if (options.command !== undefined) state.command = options.command;

  await saveLoopState(paths.statePath, state);
  emit(options, 'start', state, `Loop ${name} started`);

  if (options.dryRun) {
    state.status = 'idle';
    state.updatedAt = new Date().toISOString();
    await saveLoopState(paths.statePath, state);
    emit(options, 'dry-run', state, 'Dry run complete');
    return state;
  }

  try {
    while (shouldContinue(state, paths)) {
      state.iteration += 1;
      state.updatedAt = new Date().toISOString();
      await saveLoopState(paths.statePath, state);
      emit(options, 'iteration-start', state, `Iteration ${state.iteration} starting`);

      const result = mode === 'command'
        ? await runShellCommand(options.command!, projectPath, timeoutMs)
        : await runCodexExec(options, state, timeoutMs);

      state.lastExitCode = result.code;
      state.lastOutput = truncate(result.stdout || result.stderr, 8_000);
      if (result.code === 0 || result.code === null) {
        delete state.lastError;
      } else {
        state.lastError = truncate(result.stderr || result.stdout, 8_000);
      }
      state.updatedAt = new Date().toISOString();
      await saveLoopState(paths.statePath, state);
      emit(options, 'iteration-complete', state, `Iteration ${state.iteration} exited with ${result.code ?? result.signal ?? 'unknown'}`);

      if (existsSync(untilFile)) {
        state.status = 'completed';
        state.updatedAt = new Date().toISOString();
        await saveLoopState(paths.statePath, state);
        emit(options, 'complete', state, `Completion marker found: ${untilFile}`);
        return state;
      }

      if (result.code !== 0 && result.code !== null) {
        state.status = 'failed';
        state.updatedAt = new Date().toISOString();
        await saveLoopState(paths.statePath, state);
        emit(options, 'error', state, `Iteration failed with exit code ${result.code}`);
        return state;
      }

      if (!shouldContinue(state, paths)) break;
      emit(options, 'sleep', state, `Sleeping ${intervalSeconds}s`);
      await sleep(intervalSeconds * 1000);
    }

    state.status = existsSync(paths.stopPath) ? 'stopped' : 'completed';
    state.updatedAt = new Date().toISOString();
    await saveLoopState(paths.statePath, state);
    emit(options, state.status === 'stopped' ? 'stop' : 'complete', state);
    return state;
  } catch (error) {
    state.status = 'failed';
    state.lastError = error instanceof Error ? error.message : String(error);
    state.updatedAt = new Date().toISOString();
    await saveLoopState(paths.statePath, state);
    emit(options, 'error', state, state.lastError);
    return state;
  }
}

async function runCodexExec(options: LoopRunOptions, state: LoopState, timeoutMs: number): Promise<LoopCommandResult> {
  const args = ['exec', '--sandbox', options.sandbox ?? 'workspace-write'];
  if (options.skipGitRepoCheck !== false) args.push('--skip-git-repo-check');
  if (options.model) args.push('-m', options.model);
  args.push(buildCodexLoopPrompt(state));
  return runProcess(options.codexCommand ?? 'codex', args, state.projectPath, timeoutMs);
}

async function runShellCommand(command: string, cwd: string, timeoutMs: number): Promise<LoopCommandResult> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, {
      cwd,
      shell: true,
      env: { ...process.env, FORCE_COLOR: '0' },
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    collectChild(child, timeoutMs, resolve, reject);
  });
}

async function runProcess(command: string, args: string[], cwd: string, timeoutMs: number): Promise<LoopCommandResult> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd,
      env: { ...process.env, FORCE_COLOR: '0' },
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    collectChild(child, timeoutMs, resolve, reject);
  });
}

function collectChild(
  child: ReturnType<typeof spawn>,
  timeoutMs: number,
  resolve: (result: LoopCommandResult) => void,
  reject: (error: Error) => void
): void {
  let stdout = '';
  let stderr = '';
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    child.kill('SIGTERM');
  }, timeoutMs);

  child.stdout?.on('data', data => { stdout += data.toString(); });
  child.stderr?.on('data', data => { stderr += data.toString(); });
  child.on('error', err => {
    clearTimeout(timer);
    reject(err);
  });
  child.on('close', (code, signal) => {
    clearTimeout(timer);
    if (timedOut) {
      resolve({ code: 124, signal, stdout, stderr: stderr || `Timed out after ${timeoutMs}ms` });
      return;
    }
    resolve({ code, signal, stdout, stderr });
  });
}

async function saveLoopState(statePath: string, state: LoopState): Promise<void> {
  await fs.ensureDir(path.dirname(statePath));
  await fs.writeJson(statePath, state, { spaces: 2 });
}

function shouldContinue(state: LoopState, paths: LoopPaths): boolean {
  if (state.status !== 'running') return false;
  if (existsSync(paths.stopPath)) return false;
  if (existsSync(state.untilFile)) return false;
  return state.maxIterations === 0 || state.iteration < state.maxIterations;
}

function emit(options: LoopRunOptions, type: LoopEvent['type'], state: LoopState, message?: string): void {
  const event: LoopEvent = { type, state: { ...state } };
  if (message !== undefined) event.message = message;
  options.onEvent?.(event);
}

function clampInteger(value: number, min: number, max: number): number {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, Math.floor(value)));
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max)}\n...[truncated]`;
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Shared Ruflo MCP configuration for Codex generators, migrations, and init.
 */

import type { McpServerConfig } from './types.js';

export const RUFLO_MCP_SERVER_NAME = 'ruflo';
export const RUFLO_MCP_PACKAGE = 'ruflo@latest';
export const RUFLO_MCP_STARTUP_TIMEOUT_SEC = 120;

export interface CodexMcpRegistration {
  name?: unknown;
  transport?: {
    type?: unknown;
    command?: unknown;
    args?: unknown;
  } | null;
  startup_timeout_sec?: unknown;
}

export interface CodexCliInvocation {
  command: string;
  prefixArgs: string[];
}

export function getCodexCliInvocation(
  lookupOutput: string,
  platform: NodeJS.Platform = process.platform,
  commandShell = process.env.ComSpec || 'cmd.exe',
): CodexCliInvocation {
  const matches = lookupOutput.split(/\r?\n/).map(value => value.trim()).filter(Boolean);
  if (matches.length === 0) {
    throw new Error('Codex CLI path not found');
  }

  if (platform !== 'win32') {
    return { command: matches[0]!, prefixArgs: [] };
  }

  const executable = matches.find(match => /\.exe$/i.test(match));
  if (executable) {
    return { command: executable, prefixArgs: [] };
  }

  // npm installs expose extensionless and .cmd shims, neither of which can
  // be launched reliably with execFileSync on Windows. Resolve the shim via
  // cmd.exe without interpolating any user-controlled arguments.
  return { command: commandShell, prefixArgs: ['/d', '/s', '/c', 'codex'] };
}

export function getRufloMcpServerConfig(
  platform: NodeJS.Platform = process.platform,
  toolTimeout = 120,
): McpServerConfig {
  const args = ['-y', RUFLO_MCP_PACKAGE, 'mcp', 'start'];

  return platform === 'win32'
    ? {
        name: RUFLO_MCP_SERVER_NAME,
        command: 'cmd',
        args: ['/c', 'npx', ...args],
        enabled: true,
        startupTimeout: RUFLO_MCP_STARTUP_TIMEOUT_SEC,
        toolTimeout,
      }
    : {
        name: RUFLO_MCP_SERVER_NAME,
        command: 'npx',
        args,
        enabled: true,
        startupTimeout: RUFLO_MCP_STARTUP_TIMEOUT_SEC,
        toolTimeout,
      };
}

export function renderMcpServerToml(server: McpServerConfig): string[] {
  const lines = [
    `[mcp_servers.${server.name}]`,
    `command = ${tomlString(server.command)}`,
  ];

  if (server.args && server.args.length > 0) {
    lines.push(`args = [${server.args.map(tomlString).join(', ')}]`);
  }

  lines.push(`enabled = ${server.enabled ?? true}`);

  if (server.startupTimeout !== undefined) {
    lines.push(`startup_timeout_sec = ${server.startupTimeout}`);
  }

  if (server.toolTimeout !== undefined) {
    lines.push(`tool_timeout_sec = ${server.toolTimeout}`);
  }

  if (server.env && Object.keys(server.env).length > 0) {
    lines.push('', `[mcp_servers.${server.name}.env]`);
    for (const [key, value] of Object.entries(server.env)) {
      lines.push(`${key} = ${tomlString(value)}`);
    }
  }

  return lines;
}

export function getRufloMcpAddCommand(platform: NodeJS.Platform = process.platform): string {
  const server = getRufloMcpServerConfig(platform);
  return ['codex', 'mcp', 'add', RUFLO_MCP_SERVER_NAME, '--', server.command, ...(server.args ?? [])].join(' ');
}

export function hasExpectedRufloMcpTransport(
  registration: CodexMcpRegistration,
  platform: NodeJS.Platform = process.platform,
): boolean {
  const expected = getRufloMcpServerConfig(platform);
  const transport = registration.transport;
  if (!transport || transport.type !== 'stdio' || transport.command !== expected.command) {
    return false;
  }

  return Array.isArray(transport.args)
    && transport.args.length === expected.args?.length
    && transport.args.every((arg, index) => arg === expected.args?.[index]);
}

export function hasExpectedRufloMcpTimeout(registration: CodexMcpRegistration): boolean {
  return typeof registration.startup_timeout_sec === 'number'
    && registration.startup_timeout_sec >= RUFLO_MCP_STARTUP_TIMEOUT_SEC;
}

export function upsertMcpServerStartupTimeout(
  config: string,
  serverName = RUFLO_MCP_SERVER_NAME,
  timeoutSec = RUFLO_MCP_STARTUP_TIMEOUT_SEC,
): string {
  const eol = config.includes('\r\n') ? '\r\n' : '\n';
  const lines = config.split(/\r?\n/);
  const header = `[mcp_servers.${serverName}]`;
  const start = lines.findIndex(line => line.trim() === header);

  if (start < 0) {
    throw new Error(`${header} not found in Codex config`);
  }

  let end = lines.length;
  for (let index = start + 1; index < lines.length; index += 1) {
    if (lines[index]?.trim().startsWith('[')) {
      end = index;
      break;
    }
  }

  const timeoutPattern = /^\s*startup_timeout_sec\s*=/;
  for (let index = start + 1; index < end; index += 1) {
    const line = lines[index] ?? '';
    if (timeoutPattern.test(line)) {
      const parsed = line.match(/^(\s*startup_timeout_sec\s*=\s*)([0-9][0-9_]*)(.*)$/);
      const currentValue = parsed ? Number(parsed[2]!.replace(/_/g, '')) : Number.NaN;
      if (Number.isFinite(currentValue) && currentValue >= timeoutSec) {
        return config;
      }
      lines[index] = parsed
        ? `${parsed[1]}${timeoutSec}${parsed[3]}`
        : `startup_timeout_sec = ${timeoutSec}`;
      return lines.join(eol);
    }
  }

  lines.splice(end, 0, `startup_timeout_sec = ${timeoutSec}`);
  return lines.join(eol);
}

function tomlString(value: string): string {
  return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

